// 2. Mock SQL Connection & Pool that intercepts queries and operates against db fixture
function createMockConnection() {
  return {
    async beginTransaction() {},
    async commit() {},
    async rollback() {},
    release() {},
    async execute(sql, params = []) {
      const s = sql.replace(/\s+/g, " ").trim();

      // SELECT 1 FROM consultancy_members
      if (s.includes("SELECT 1 FROM consultancy_members")) {
        const memId = params[0];
        const uId = params[1];
        const match = db.consultancy_members.find((m) => m.id === Number(memId) && m.user_id === Number(uId));
        return [match ? [{ 1: 1 }] : [], []];
      }

      // SELECT wa.id, wa.public_id ... FROM workout_assignments wa (by public_id or by id)
      if (s.includes("FROM workout_assignments wa")) {
        let a = null;
        if (s.includes("wa.public_id = ?")) {
          a = db.workout_assignments.find((x) => x.public_id === params[0]);
        } else if (s.includes("wa.id = ?")) {
          a = db.workout_assignments.find((x) => x.id === Number(params[0]));
        } else {
          a = db.workout_assignments[0];
        }
        if (!a) return [[], []];
        return [[{
          id: a.id,
          public_id: a.public_id,
          consultancy_id: a.consultancy_id,
          student_membership_id: a.student_membership_id,
          workout_version_id: a.workout_version_id,
          status: a.status,
          version_public_id: "wv-60",
          version_number: 1,
          workout_id: 50,
        }], []];
      }

      // SELECT id, public_id, title, sort_order FROM workout_blocks WHERE public_id = ? AND workout_version_id = ?
      if (s.includes("FROM workout_blocks") && s.includes("public_id = ? AND workout_version_id = ?")) {
        const bPubId = params[0];
        const vId = params[1];
        const b = db.workout_blocks.find((x) => x.workout_version_id === Number(vId) && x.public_id === bPubId);
        return [b ? [b] : [], []];
      }

      // SELECT wb.id, wb.public_id, wb.title FROM workout_blocks wb WHERE wb.workout_version_id = ? ORDER BY wb.sort_order ASC LIMIT 1
      if (s.includes("FROM workout_blocks wb") && s.includes("wb.workout_version_id = ?") && s.includes("LIMIT 1")) {
        const vId = params[0];
        const blocks = db.workout_blocks.filter((x) => x.workout_version_id === Number(vId));
        return [blocks.length > 0 ? [blocks[0]] : [], []];
      }

      // SELECT wes.id, wes.public_id ... FROM workout_execution_sessions wes WHERE wes.workout_assignment_id = ? AND wes.status = 'IN_PROGRESS'
      if (s.includes("FROM workout_execution_sessions wes") && s.includes("wes.status = 'IN_PROGRESS'")) {
        const assignId = params[0];
        const sessions = db.workout_execution_sessions.filter((x) => x.workout_assignment_id === Number(assignId) && x.status === "IN_PROGRESS");
        const rows = sessions.map((sess) => {
          const b = db.workout_blocks.find((blk) => blk.id === sess.workout_block_id);
          return {
            id: sess.id,
            public_id: sess.public_id,
            consultancy_id: sess.consultancy_id,
            student_membership_id: sess.student_membership_id,
            workout_assignment_id: sess.workout_assignment_id,
            workout_version_id: sess.workout_version_id,
            workout_block_id: sess.workout_block_id,
            status: sess.status,
            started_at: sess.started_at,
            completed_at: sess.completed_at,
            created_at: sess.created_at,
            updated_at: sess.updated_at,
            workout_block_public_id: b?.public_id || null,
            workout_block_title: b?.title || null,
          };
        });
        return [rows, []];
      }

      // SELECT ... FROM workout_execution_sessions WHERE public_id = ?
      if (s.includes("FROM workout_execution_sessions") && s.includes("public_id = ?")) {
        const sPubId = params[0];
        const sess = db.workout_execution_sessions.find((x) => x.public_id === sPubId);
        if (!sess) return [[], []];
        const b = db.workout_blocks.find((blk) => blk.id === sess.workout_block_id);
        const a = db.workout_assignments.find((asg) => asg.id === sess.workout_assignment_id);
        return [[{
          id: sess.id,
          public_id: sess.public_id,
          consultancy_id: sess.consultancy_id,
          student_membership_id: sess.student_membership_id,
          workout_assignment_id: sess.workout_assignment_id,
          workout_version_id: sess.workout_version_id,
          workout_block_id: sess.workout_block_id,
          status: sess.status,
          started_at: sess.started_at,
          completed_at: sess.completed_at,
          created_at: sess.created_at,
          updated_at: sess.updated_at,
          assignment_public_id: a?.public_id || "wa-70",
          version_public_id: "wv-60",
          workout_block_public_id: b?.public_id || null,
          workout_block_title: b?.title || null,
        }], []];
      }

      // Snapshot Prescribed Sets: SELECT ... FROM workout_blocks wb INNER JOIN workout_block_items wbi ... WHERE wb.id = ?
      if (s.includes("FROM workout_blocks wb") && s.includes("WHERE wb.id = ?")) {
        const targetBlockId = Number(params[0]);
        const items = db.workout_block_items.filter((i) => i.block_id === targetBlockId);
        const rows = [];
        for (const item of items) {
          const sets = db.workout_item_sets.filter((st) => st.block_item_id === item.id);
          for (const set of sets) {
            rows.push({
              workout_item_set_id: set.id,
              block_item_id: item.id,
              set_number: set.set_number,
              set_type: set.set_type,
              target_reps: set.target_reps,
              target_reps_max: null,
              target_load_kg: set.target_load_kg,
              target_rest_seconds: null,
            });
          }
        }
        return [rows, []];
      }

      // INSERT INTO workout_execution_sessions
      if (s.includes("INSERT INTO workout_execution_sessions")) {
        const id = ++autoIncrement;
        const [pubId, cId, mId, aId, vId, bId] = params;
        const row = {
          id,
          public_id: pubId,
          consultancy_id: Number(cId),
          student_membership_id: Number(mId),
          workout_assignment_id: Number(aId),
          workout_version_id: Number(vId),
          workout_block_id: bId != null ? Number(bId) : null,
          status: "IN_PROGRESS",
          started_at: new Date(),
          completed_at: null,
          created_at: new Date(),
          updated_at: new Date(),
        };
        db.workout_execution_sessions.push(row);
        return [{ insertId: id }, []];
      }

      // INSERT INTO workout_execution_sets
      if (s.includes("INSERT INTO workout_execution_sets")) {
        const id = ++autoIncrement;
        const [pubId, sId, wisId, biId, sNum, sType, pReps, pRepsMax, pLoad, pRest, aReps, aLoad, isSkipped, compAt] = params;
        const bi = db.workout_block_items.find((x) => x.id === Number(biId));
        const row = {
          id,
          public_id: pubId,
          execution_session_id: Number(sId),
          workout_item_set_id: wisId != null ? Number(wisId) : null,
          block_item_id: Number(biId),
          block_item_public_id: bi?.public_id || "bi-unknown",
          set_number: Number(sNum),
          set_type: sType,
          prescribed_reps: pReps,
          prescribed_reps_max: pRepsMax,
          prescribed_load_kg: pLoad,
          prescribed_rest_seconds: pRest,
          actual_reps: aReps,
          actual_load_kg: aLoad,
          is_skipped: Number(isSkipped || 0),
          completed_at: compAt,
          created_at: new Date(),
          updated_at: new Date(),
        };
        db.workout_execution_sets.push(row);
        return [{ insertId: id }, []];
      }

      // SELECT ... FROM workout_execution_sets wex WHERE wex.execution_session_id = ? (without GROUP BY)
      if (s.includes("FROM workout_execution_sets wex") && s.includes("WHERE wex.execution_session_id = ?") && !s.includes("GROUP BY")) {
        const sId = Number(params[0]);
        const sets = db.workout_execution_sets.filter((x) => x.execution_session_id === sId);
        return [sets, []];
      }

      // SELECT ... FROM workout_execution_sets wex WHERE wex.public_id = ? AND wex.execution_session_id = ?
      if (s.includes("FROM workout_execution_sets wex") && s.includes("wex.public_id = ? AND wex.execution_session_id = ?")) {
        const [setPubId, sId] = params;
        const match = db.workout_execution_sets.find((x) => x.public_id === setPubId && x.execution_session_id === Number(sId));
        return [match ? [match] : [], []];
      }

      // UPDATE workout_execution_sets SET completed_at = ?, actual_reps = ?, actual_load_kg = ?, is_skipped = ?
      if (s.includes("UPDATE workout_execution_sets SET completed_at = ?, actual_reps = ?, actual_load_kg = ?, is_skipped = ?")) {
        const [now, reps, load, isSkipped, targetId] = params;
        const set = db.workout_execution_sets.find((x) => x.id === Number(targetId));
        if (set) {
          set.completed_at = now;
          set.actual_reps = reps;
          set.actual_load_kg = load;
          set.is_skipped = Number(isSkipped);
        }
        return [{ affectedRows: 1 }, []];
      }

      // UPDATE workout_execution_sets SET completed_at = NOW(3), is_skipped = 1 WHERE execution_session_id = ? AND completed_at IS NULL
      if (s.includes("UPDATE workout_execution_sets SET completed_at = NOW(3), is_skipped = 1")) {
        const sId = Number(params[0]);
        let affected = 0;
        for (const st of db.workout_execution_sets) {
          if (st.execution_session_id === sId && st.completed_at == null) {
            st.completed_at = new Date();
            st.is_skipped = 1;
            affected++;
          }
        }
        return [{ affectedRows: affected }, []];
      }

      // UPDATE workout_execution_sessions SET status = 'COMPLETED'
      if (s.includes("UPDATE workout_execution_sessions SET status = 'COMPLETED'")) {
        const sId = Number(params[0]);
        const sess = db.workout_execution_sessions.find((x) => x.id === sId);
        if (sess) {
          sess.status = "COMPLETED";
          sess.completed_at = new Date();
        }
        return [{ affectedRows: 1 }, []];
      }

      // UPDATE workout_execution_sessions SET status = 'ABANDONED'
      if (s.includes("UPDATE workout_execution_sessions SET status = 'ABANDONED'")) {
        const sId = Number(params[0]);
        const sess = db.workout_execution_sessions.find((x) => x.id === sId);
        if (sess) {
          sess.status = "ABANDONED";
        }
        return [{ affectedRows: 1 }, []];
      }

      // SELECT COUNT(*) AS performed_count FROM workout_execution_sets WHERE execution_session_id = ? AND completed_at IS NOT NULL AND (is_skipped = 0 OR is_skipped IS NULL)
      if (s.includes("COUNT(*) AS performed_count")) {
        const sId = Number(params[0]);
        const performed = db.workout_execution_sets.filter(
          (x) => x.execution_session_id === sId && x.completed_at != null && (x.is_skipped === 0 || x.is_skipped == null)
        ).length;
        return [[{ performed_count: performed }], []];
      }

      // SELECT COUNT(*) AS pending_count FROM workout_execution_sets WHERE execution_session_id = ? AND completed_at IS NULL
      if (s.includes("COUNT(*) AS pending_count")) {
        const sId = Number(params[0]);
        const pending = db.workout_execution_sets.filter((x) => x.execution_session_id === sId && x.completed_at == null).length;
        return [[{ pending_count: pending }], []];
      }

      // resolveLegacySessionBlocks query: SELECT wb.id AS block_id ... FROM workout_execution_sets wex ... GROUP BY wb.id
      if (s.includes("GROUP BY wb.id, wb.public_id, wb.title, wb.sort_order")) {
        const sId = Number(params[0]);
        const sets = db.workout_execution_sets.filter((x) => x.execution_session_id === sId);
        const map = new Map();
        for (const st of sets) {
          const item = db.workout_block_items.find((i) => i.id === st.block_item_id);
          const block = db.workout_blocks.find((b) => b.id === item?.block_id);
          if (!block) continue;
          if (!map.has(block.id)) {
            map.set(block.id, {
              block_id: block.id,
              block_public_id: block.public_id,
              block_title: block.title,
              total_sets: 0,
              completed_sets: 0,
              sort_order: block.sort_order,
            });
          }
          const entry = map.get(block.id);
          entry.total_sets++;
          if (st.completed_at != null && (st.is_skipped === 0 || st.is_skipped == null)) {
            entry.completed_sets++;
          }
        }
        const rows = Array.from(map.values()).sort((a, b) => b.completed_sets - a.completed_sets || a.sort_order - b.sort_order);
        return [rows, []];
      }

      return [[], []];
    },
    async query(sql, params) {
      return this.execute(sql, params);
    },
  };
}

// Attach mock pool into globalThis._mysqlPool
globalThis._mysqlPool = {
  async getConnection() {
    return createMockConnection();
  },
};

// Import the REAL production functions from lib/training-v2/execution-repository.ts
const {
  startOrResumeWorkoutExecution,
  completeWorkoutExecutionSet,
  completeWorkoutExecution,
  resolveLegacySessionBlocks,
  TrainingSessionConflictError,
} = await import("../lib/training-v2/execution-repository.ts");

const studentCtx = {
  consultancyId: 100,
  membershipId: 10,
  userId: 1,
  isStudent: true,
  hasRole: (r) => r === "STUDENT",
};

let passed = 0;
let total = 0;

async function runRealTest(name, fn) {
  total++;
  try {
    resetDb();
    await fn();
    console.log(`  [PASS] ${name}`);
    passed++;
  } catch (err) {
    console.error(`  [FAIL] ${name}`);
    console.error(`         ${err.message}`);
    process.exitCode = 1;
  }
}

// TEST 1: Division Scoping Real Snapshotting
await runRealTest("REAL INTEGRATION: Snapshot scoped strictly to chosen division block (Quarta • Costas)", async () => {
  const session = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  
  assert.equal(session.workoutBlockPublicId, "blk-quarta");
  assert.equal(session.workoutBlockTitle, "Quarta • Costas");
  
  // Verify sets in DB for this session
  const sessionSets = db.workout_execution_sets.filter((s) => s.execution_session_id === db.workout_execution_sessions[0].id);
  
  // Quarta has exactly 6 sets (3 on bi-203 + 3 on bi-204)
  assert.equal(sessionSets.length, 6, "Must contain exactly 6 sets from Quarta");
  
  // Verify NO sets from Segunda (bi-201, bi-202) or Sexta (bi-205) were inserted
  const foreignItemSets = sessionSets.filter((s) => [201, 202, 205].includes(s.block_item_id));
  assert.equal(foreignItemSets.length, 0, "No foreign division sets allowed in session");
});

// TEST 2: Active Session Conflict Detection
await runRealTest("REAL INTEGRATION: Starting another division while one is in progress throws TrainingSessionConflictError", async () => {
  // Start Quarta
  await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  
  // Try to start Sexta without conflict resolution
  await assert.rejects(
    async () => {
      await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-sexta");
    },
    (err) => {
      assert.ok(err instanceof TrainingSessionConflictError);
      assert.equal(err.code, "ACTIVE_SESSION_CONFLICT");
      assert.equal(err.activeSession.workoutBlockPublicId, "blk-quarta");
      assert.equal(err.targetBlock.publicId, "blk-sexta");
      assert.match(err.message, /encerrá-la como interrompida/i);
      return true;
    }
  );
});

// TEST 3: Conflict Resolution ABANDON (Encerrar como interrompida)
await runRealTest("REAL INTEGRATION: ABANDON marks previous session ABANDONED without deleting recorded sets or data", async () => {
  // Start Quarta
  const s1 = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  
  // Perform 2 sets with real reps and loads
  const set1 = s1.sets[0];
  const set2 = s1.sets[1];
  await completeWorkoutExecutionSet(studentCtx, s1.publicId, set1.publicId, { actualReps: 8, actualLoadKg: 75 });
  await completeWorkoutExecutionSet(studentCtx, s1.publicId, set2.publicId, { actualReps: 8, actualLoadKg: 75 });

  // Resolve conflict: ABANDON (Encerrar como interrompida) to start Sexta
  const s2 = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-sexta", { resolveConflict: "ABANDON" });

  assert.equal(s2.workoutBlockPublicId, "blk-sexta");
  
  // Verify previous session in DB
  const oldSess = db.workout_execution_sessions.find((s) => s.public_id === s1.publicId);
  assert.equal(oldSess.status, "ABANDONED");
  
  // CRITICAL: Verify that old session sets were NOT deleted and retain their actual metrics
  const oldSet1 = db.workout_execution_sets.find((s) => s.public_id === set1.publicId);
  assert.equal(oldSet1.actual_reps, 8);
  assert.equal(oldSet1.actual_load_kg, 75);
  assert.ok(oldSet1.completed_at != null);
});

// TEST 4: Optional Reps and Load Null Preservation
await runRealTest("REAL INTEGRATION: Empty reps and loads are preserved as NULL without coercion to 0 or prescribed target", async () => {
  const s = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  const set1 = s.sets[0];

  // Complete set with null/empty metrics (bodyweight / optional)
  const completed = await completeWorkoutExecutionSet(studentCtx, s.publicId, set1.publicId, {
    actualReps: null,
    actualLoadKg: null,
  });

  assert.equal(completed.actualReps, null, "actualReps must be null");
  assert.equal(completed.actualLoadKg, null, "actualLoadKg must be null");
  assert.equal(completed.isSkipped, false);
  assert.ok(completed.completedAt != null);

  // Check DB row
  const dbSet = db.workout_execution_sets.find((x) => x.public_id === set1.publicId);
  assert.equal(dbSet.actual_reps, null);
  assert.equal(dbSet.actual_load_kg, null);
  assert.equal(dbSet.is_skipped, 0);
});

// TEST 5: Skipped Set Metrics
await runRealTest("REAL INTEGRATION: Skipping a set records is_skipped=1 with null reps/load", async () => {
  const s = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  const set1 = s.sets[0];

  const completed = await completeWorkoutExecutionSet(studentCtx, s.publicId, set1.publicId, {
    isSkipped: true,
  });

  assert.equal(completed.isSkipped, true);
  assert.equal(completed.actualReps, null);
  assert.equal(completed.actualLoadKg, null);

  const dbSet = db.workout_execution_sets.find((x) => x.public_id === set1.publicId);
  assert.equal(dbSet.is_skipped, 1);
  assert.equal(dbSet.actual_reps, null);
});

// TEST 6: Standard Completion Guard
await runRealTest("REAL INTEGRATION: Normal completion fails when pending sets exist", async () => {
  const s = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");

  // Attempting completion without allowEarlyCompletion when 6 sets are pending
  await assert.rejects(
    async () => {
      await completeWorkoutExecution(studentCtx, s.publicId);
    },
    (err) => {
      assert.equal(err.code, "WORKOUT_EXECUTION_HAS_PENDING_SETS");
      assert.match(err.message, /6 séries pendentes/i);
      return true;
    }
  );
});

// TEST 7: Early Completion with Performed Sets
await runRealTest("REAL INTEGRATION: allowEarlyCompletion marks only pending sets as skipped and completes session", async () => {
  const s = await startOrResumeWorkoutExecution(studentCtx, "wa-70", "blk-quarta");
  
  // Complete 2 sets with real metrics
  await completeWorkoutExecutionSet(studentCtx, s.publicId, s.sets[0].publicId, { actualReps: 10, actualLoadKg: 70 });
  await completeWorkoutExecutionSet(studentCtx, s.publicId, s.sets[1].publicId, { actualReps: 10, actualLoadKg: 70 });

  // Complete early
  const completedSession = await completeWorkoutExecution(studentCtx, s.publicId, { allowEarlyCompletion: true });

  assert.equal(completedSession.status, "COMPLETED");

  // Verify that sets 0 and 1 are completed with isSkipped: false
  assert.equal(completedSession.sets[0].isSkipped, false);
  assert.equal(completedSession.sets[0].actualReps, 10);
  assert.equal(completedSession.sets[1].isSkipped, false);

  // Verify that remaining 4 sets were marked isSkipped: true
  for (let i = 2; i < 6; i++) {
    assert.equal(completedSession.sets[i].isSkipped, true, `Set ${i} must be skipped`);
    assert.ok(completedSession.sets[i].completedAt != null);
  }
});

